-- UNDO 0178: put the 22 pre-revamp ob_kb rows back (saved 20 Nov 2026 before the change) and remove the kb_* help-bot rows.
-- The edge function kr8-help-ai was version 14 before this change; its source is the parent of this commit (supabase/functions/kr8-help-ai/index.ts).
begin;
delete from public.ob_kb where key like 'kb\_%';
on conflict (key) do update set lang=excluded.lang, value_text=excluded.value_text, value_num=excluded.value_num, verified_source=excluded.verified_source, updated_at=excluded.updated_at;
commit;
